test('empty events and bounded draws do not imply a complete zero-score event',async({page})=>{let d=await open(page,'empty');await expect(d).toContainText('No public tournaments found');d=await division(page,'limited');await expect(d).toContainText('No partial standings');await expect(d.locator('.competition-metrics')).toHaveCount(0);await d.getByRole('button',{name:'Draw',exact:true}).click();await expect(d).toContainText('No partial standings');await expect(d.locator('.competition-fixture')).toHaveCount(0)})
test('device back preserves the selected event before returning to leagues',async({page})=>{const d=await division(page);const back=()=>page.evaluate(()=>(window as unknown as {tournamentFixture:{back:()=>void}}).tournamentFixture.back());await back();await expect(d.getByRole('button',{name:/^Open division/})).toBeVisible();await back();await expect(d.getByLabel('Find a tournament')).toBeVisible();await back();await expect(page.getByRole('dialog',{name:'Competitions',exact:true})).toBeVisible()})

for(const width of [320,390]){
 test('find published matches locally by player, day and court at '+width+'px',async({page},info)=>{
  await page.setViewportSize({width,height:844});const d=await division(page);await d.getByRole('button',{name:'Schedule',exact:true}).click()
  const calls=()=>page.evaluate(()=>(window as unknown as {tournamentFixture:{state:{calls:number}}}).tournamentFixture.state.calls),before=await calls()
  const filters=d.locator('.schedule-filters > summary')
  await expect(filters).toHaveText('Filter schedule')
  await expect(d.getByLabel('Match court',{exact:true})).toBeHidden()
  await expect(d.locator('.competition-fixture .fixture-schedule').first()).toBeInViewport()
  await filters.click()
  await d.getByLabel('Player or team name',{exact:true}).fill('Jordan');await d.getByRole('button',{name:'Apply filters',exact:true}).click();await expect(d.locator('[data-tournament-filter-status]')).toContainText('1 of 2 matches');await expect(d.locator('.competition-fixture')).toHaveCount(1);await expect(d.locator('.competition-fixture')).toContainText('Jordan Serve');await expect(d.locator('.competition-match-groups h4')).toHaveText('Sunday, November 15, 2026')
  await d.getByLabel('Match day',{exact:true}).selectOption('2026-11-14');await d.getByRole('button',{name:'Apply filters',exact:true}).click();await expect(d).toContainText('No matches fit these filters');await expect(d.locator('.competition-fixture')).toHaveCount(0)
  await d.locator('.competition-empty').getByRole('button',{name:'Show all matches',exact:true}).click()
  await expect(d.locator('[data-tournament-filter-status]')).toBeFocused()
  await expect(d.locator('[data-tournament-filter-status]')).toBeInViewport()
  await expect(d.locator('.competition-fixture')).toHaveCount(2)
  await expect(d.getByLabel('Match court',{exact:true})).toBeHidden()
  await filters.click();await d.getByLabel('Match day',{exact:true}).selectOption('2026-11-14');await d.getByLabel('Match court',{exact:true}).selectOption('2');await d.getByRole('button',{name:'Apply filters',exact:true}).click();await expect(d.locator('.competition-fixture')).toHaveCount(1);expect(await calls()).toBe(before)
  await page.addStyleTag({content:':root{font-size:22px!important}'});await bounded(page);await page.screenshot({path:info.outputPath('tournament-match-finder.png')})
  await expect(filters).toContainText('2 active')
  await filters.click()
  await expect(d.getByLabel('Match court',{exact:true})).toBeHidden()
  await expect(d.locator('.competition-fixture')).toHaveCount(1)
  await d.getByRole('button',{name:'Results',exact:true}).click()
  const resultFilters=d.locator('.results-filters > summary')
  await expect(resultFilters).toHaveText('Filter results')
  await resultFilters.click()
  await d.getByLabel('Player or team name',{exact:true}).fill('Jordan')
  await d.getByRole('button',{name:'Apply filters',exact:true}).click()
  await expect(resultFilters).toContainText('1 active')
  await expect(d.locator('.competition-fixture')).toHaveCount(0)
  await d.locator('.competition-empty').getByRole('button',{name:'Show all results',exact:true}).click()
  await expect(d.getByLabel('Player or team name',{exact:true})).toBeHidden()
  await expect(d.locator('.competition-fixture')).toHaveCount(1)
  expect(await calls()).toBe(before)
 })
 test('match filters preserve refresh and tabs then reset for a newly opened division at '+width+'px',async({page})=>{
  await page.setViewportSize({width,height:844});const d=await division(page);await d.getByRole('button',{name:'Schedule',exact:true}).click();await d.locator('.schedule-filters > summary').click();await d.getByLabel('Match day',{exact:true}).selectOption('2026-11-14');await d.getByRole('button',{name:'Apply filters',exact:true}).click();await expect(d.locator('.competition-fixture')).toHaveCount(1)
  await d.getByRole('button',{name:'Draw',exact:true}).click();await expect(d.locator('.competition-fixture')).toHaveCount(2)
  const drawFilter=d.locator('.draw-filters > summary'),round=d.getByLabel('Round',{exact:true}),calls=await requestCount(page)
  await expect(round).toBeHidden();await drawFilter.click();await round.selectOption('Round 2');await d.getByRole('button',{name:'Apply filters',exact:true}).click()
  await expect(drawFilter).toContainText('1 active');await expect(d.getByRole('heading',{name:'Round 2',exact:true})).toBeVisible();await expect(d.getByRole('heading',{name:'Round 1',exact:true})).toHaveCount(0)
  await expect(d.locator('.competition-fixture')).toContainText('Court 1');expect(await requestCount(page)).toBe(calls)
  await d.getByRole('button',{name:'Schedule',exact:true}).click();await expect(d.getByLabel('Match day',{exact:true})).toHaveValue('2026-11-14');await d.getByRole('button',{name:'Refresh tournaments',exact:true}).click();await expect(d.locator('.competition-fixture')).toHaveCount(1);await expect(d.getByLabel('Match day',{exact:true})).toHaveValue('2026-11-14')
  await d.getByRole('button',{name:'Draw',exact:true}).click();await expect(round).toHaveValue('Round 2');await d.getByRole('button',{name:'Clear filters',exact:true}).click();await expect(round).toBeHidden();await expect(d.locator('.competition-match-groups .competition-match-group')).toHaveCount(2)
  await d.getByRole('button',{name:'← Event',exact:true}).click();await d.getByRole('button',{name:/^Open division/}).click();await d.getByRole('button',{name:'Schedule',exact:true}).click();await expect(d.getByLabel('Match day',{exact:true})).toHaveValue('');await expect(d.locator('.competition-fixture')).toHaveCount(2)
 })
}

