const requestCount=(page:Page)=>page.evaluate(()=>(window as unknown as {tournamentFixture:{state:{calls:number}}}).tournamentFixture.state.calls)
const groupValue=(group:string)=>JSON.stringify(group)
async function standings(page:Page,mode='standings'){const d=await division(page,mode);await d.getByRole('button',{name:'Standings',exact:true}).click();return d}
async function inSheet(locator:ReturnType<Page['locator']>){return locator.evaluate(el=>{const host=el.closest('dialog')!,frame=host.getBoundingClientRect(),r=el.getBoundingClientRect();return r.top>=frame.top+host.clientTop&&r.bottom<=frame.top+host.clientTop+host.clientHeight})}
