async function entry(page:Page,mode='entry'){const d=await division(page,mode);await d.getByRole('button',{name:'Entry & registration',exact:true}).click();const e=page.getByRole('dialog',{name:'Tournament entry',exact:true});await expect(e.getByRole('heading',{name:'Tournament entry',exact:true})).toBeVisible();await expect(e.getByRole('status')).toBeEmpty();return e}
async function fillEntry(page:Page){const e=await entry(page);await e.getByLabel('Your self-rated level',{exact:true}).selectOption('4');await e.getByLabel('Partner name',{exact:true}).fill('Sam Return');await e.getByLabel('Partner self-rated level',{exact:true}).selectOption('3.5');await e.getByRole('checkbox').nth(0).check();await e.getByRole('checkbox').nth(1).check();return e}
const changePass=(page:Page,values:Record<string,unknown>)=>page.evaluate(values=>Object.assign((window as unknown as {tournamentFixture:{pass:Record<string,unknown>}}).tournamentFixture.pass,values),values)
