test('My event opens the published address for the current division in Apple Maps',async({page},info)=>{
 await page.setViewportSize({width:320,height:844})
 await page.clock.setFixedTime(new Date('2026-11-14T14:00:00Z'))
 const divisionView=await division(page,'event-pass')
 await divisionView.getByRole('button',{name:'Entry & registration',exact:true}).click()
 const pass=page.getByRole('dialog',{name:'My event',exact:true})
 const next=pass.getByRole('region',{name:'Next match',exact:true})
 const maps=next.getByRole('button',{name:'Find venue in Apple Maps',exact:true})
 const refresh=pass.getByRole('button',{name:'Refresh entry and match details',exact:true})
 await expect(next).toContainText('123 Center Court')
 const before=await requestCount(page)
 await page.evaluate(()=>{window.open=()=>{throw Error('Synthetic browser failure')}})
 await maps.click()
 await expect(next.getByRole('status')).toHaveText('Couldn’t open Apple Maps. Try again.')
 await expect(maps).toBeEnabled()

 const opened:string[]=[]
 await page.exposeFunction('recordEventVenue',(url:string)=>opened.push(url))
 await page.evaluate(()=>{
  const record=(window as unknown as {recordEventVenue:(url:string)=>void}).recordEventVenue
  window.open=url=>{record(String(url));return null}
 })
 await maps.click()
 await expect.poll(()=>opened.length).toBe(1)
 expect(new URL(opened[0]).origin).toBe('https://maps.apple.com')
 expect([...new URL(opened[0]).searchParams]).toEqual([['q','123 Center Court']])
 await expect(next.getByRole('status')).toBeEmpty()
 expect(await requestCount(page)).toBe(before)

 await changePass(page,{divisionVenue:'West Tennis Club'})
 await refresh.click()
 await expect(next).toContainText('West Tennis Club')
 await expect(next).not.toContainText('123 Center Court')
 await expect(maps).toHaveCount(0)

 await changePass(page,{divisionAddress:'59 Rally Lane, Suite A & B'})
 await refresh.click()
 await expect(next).toContainText('59 Rally Lane, Suite A & B')
 await page.addStyleTag({content:':root{font-size:22px!important}'})
 await maps.scrollIntoViewIfNeeded()
 expect(await pass.evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true)
 await page.screenshot({path:info.outputPath('tournament-my-event-venue.png')})
 await maps.click()
 await expect.poll(()=>opened.length).toBe(2)
 expect([...new URL(opened[1]).searchParams]).toEqual([['q','59 Rally Lane, Suite A & B']])
})
